import json
W,H=24,27
bg=6
g=[[bg]*W for _ in range(H)]
tile=[[1,0,6],[0,3,0],[9,6,6]]
# cluster kept at rows 12-14, cols 5-7 (true rows, unshifted since k=15>14)
for dr in range(3):
    for dc in range(3):
        g[12+dr][5+dc]=tile[dr][dc]
# true markers: k=15 row loss -> rendered rows >=15 shift +1
true_mk=[(5,12),(8,22),(9,14),(13,15),(14,10),(16,18),(20,7),(23,14),(25,20)]
for (r,c) in true_mk:
    tl=(r-1,c-1)
    for dr in range(3):
        for dc in range(3):
            g[tl[0]+dr][tl[1]+dc]=tile[dr][dc]
# checks: bounds, disjointness, cluster overlap
cells=defaultdict(int)
for r in range(H):
    for c in range(W):
        if g[r][c]!=bg: cells[(r,c)]+=1
print('overlaps:',[k for k,v in cells.items() if v>1])
print('bounds ok:', all(0<=r-1 and r+1<H and 0<=c-1 and c+1<W for r,c in true_mk))
for row in g: print(''.join(str(x) for x in row))
open('sub.json','w').write(json.dumps({"action":"submit","grid":g}))
print('saved, dims',H,W)
